css:
.fx-spb{position:relative;background:var(--surface);min-height:100vh}
.fx-spb .hd{position:sticky;top:0;z-index:5;background:color-mix(in srgb,var(--surface) 88%,transparent);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);border-bottom:1px solid var(--border)}
.fx-spb .hi{width:min(1000px,92%);margin:0 auto;display:flex;align-items:center;gap:1em;height:3.6em}
.fx-spb .hi b{font:700 1.05em var(--font-heading);display:flex;align-items:center;gap:.5em;margin-right:auto}.fx-spb .hi b::before{content:"";width:.8em;height:.8em;border-radius:30%;background:var(--accent)}
.fx-spb .hi span{font-size:.82em;opacity:.65;white-space:nowrap}.fx-spb .hi .pc{font-weight:800;opacity:1;color:var(--primary);min-width:2.8em;text-align:right;font-variant-numeric:tabular-nums}
.fx-spb .bar{position:absolute;left:0;bottom:-1px;height:3px;width:100%;background:linear-gradient(90deg,var(--primary),var(--accent));transform-origin:left;transform:scaleX(var(--p,0))}
.fx-spb article{width:min(680px,90%);margin:0 auto;padding:3.5em 0 8em}
.fx-spb .k{font-size:.78em;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--accent)}
.fx-spb h1{font-size:clamp(2.2em,6vw,3.6em);margin:.3em 0 .4em}
.fx-spb .by{opacity:.6;font-size:.9em;margin-bottom:2em}
.fx-spb .fx-art{aspect-ratio:16/8;border-radius:var(--radius);margin-bottom:2.2em}
.fx-spb h2{font-size:1.6em;margin:1.8em 0 .5em}
.fx-spb article p{font-size:1.06em;line-height:1.75;opacity:.84;margin-bottom:1.1em}
.fx-spb blockquote{margin:2em 0;padding:.2em 0 .2em 1.3em;border-left:3px solid var(--accent);font:500 1.35em/1.45 var(--font-heading)}
@media(max-width:520px){.fx-spb .hi .tl{display:none}}
